package com.chondrimaishrat.elearning.web;
import com.chondrimaishrat.elearning.assignment.*; import com.chondrimaishrat.elearning.auth.SessionAccess; import com.chondrimaishrat.elearning.user.*; import jakarta.servlet.http.HttpSession; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.time.LocalDateTime;
@Controller public class AssignmentController {private final AssignmentService assignments;private final SessionAccess access;public AssignmentController(AssignmentService a,SessionAccess x){assignments=a;access=x;}@GetMapping("/courses/{id}/assignments")public String page(@PathVariable Long id,HttpSession s,Model m){m.addAttribute("courseId",id);m.addAttribute("assignments",assignments.list(id));m.addAttribute("currentUser",s.getAttribute("currentUser"));return "assignments";}@PostMapping("/instructor/courses/{id}/assignments")public String create(@PathVariable Long id,@RequestParam String title,@RequestParam String instructions,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime dueAt,HttpSession s,RedirectAttributes r){try{assignments.create(access.requireRole(s,UserRole.INSTRUCTOR),id,title,instructions,dueAt);r.addFlashAttribute("message","Assignment published.");}catch(Exception e){r.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/courses/"+id+"/assignments";}@PostMapping("/assignments/{id}/submit")public String submit(@PathVariable Long id,@RequestParam Long courseId,@RequestParam String submissionLink,HttpSession s,RedirectAttributes r){try{assignments.submit(access.requireRole(s,UserRole.STUDENT),id,submissionLink);r.addFlashAttribute("message","Assignment submitted.");}catch(Exception e){r.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/courses/"+courseId+"/assignments";}}
